#!/usr/bin/env bash
# Tests for scripts/size-ratchet: new file over the cap fails, growth of a
# listed file fails, a shrink passes, generated files are not counted.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
tool="$here/size-ratchet"
tmp="$(mktemp -d "${TMPDIR:-/tmp}/size-ratchet-test.XXXXXX")"
trap 'rm -rf "$tmp"' EXIT
pass=0 fails=0
ok() { pass=$((pass + 1)); }
bad() { fails=$((fails + 1)); echo "FAIL: $1"; }

repo="$tmp/repo"
mkdir -p "$repo/scripts"
git -C "$repo" init -q
lines() { awk -v n="$1" 'BEGIN { for (i = 0; i < n; i++) print "x" }'; }
lines 400 >"$repo/small.go"
lines 600 >"$repo/big.go"
{ echo "// Code generated by x. DO NOT EDIT."; lines 900; } >"$repo/gen.go"
git -C "$repo" add -A
printf '600 big.go\n' >"$repo/scripts/size-ratchet.allow"
run() { "$tool" --root "$repo" "$@"; }

run >"$tmp/out" 2>&1 && ok || bad "baseline should pass: $(cat "$tmp/out")"

lines 501 >"$repo/new.go"; git -C "$repo" add -A
run >"$tmp/out" 2>&1 && bad "new file over 500 should fail" || { grep -q '^NEW   new.go' "$tmp/out" && ok || bad "NEW message: $(cat "$tmp/out")"; }
git -C "$repo" rm -qf --cached new.go; rm "$repo/new.go"

lines 500 >"$repo/edge.go"; git -C "$repo" add -A
run >"$tmp/out" 2>&1 && ok || bad "a file of exactly 500 lines passes: $(cat "$tmp/out")"

lines 601 >"$repo/big.go"
run >"$tmp/out" 2>&1 && bad "growth of a listed file should fail" || { grep -q '^GREW  big.go' "$tmp/out" && ok || bad "GREW message: $(cat "$tmp/out")"; }

lines 550 >"$repo/big.go"
run >"$tmp/out" 2>&1 && grep -q 'shrank to 550' "$tmp/out" && ok || bad "shrink should pass with a note: $(cat "$tmp/out")"

run --write >/dev/null
grep -qx '550 big.go' "$repo/scripts/size-ratchet.allow" && ok || bad "--write should lock in the shrink"
lines 560 >"$repo/big.go"
run >/dev/null 2>&1 && bad "regrowth past the locked allowance should fail" || ok

lines 100 >"$repo/big.go"
run --write >/dev/null
grep -q big.go "$repo/scripts/size-ratchet.allow" && bad "--write should drop a file under the cap" || ok

# Raise check against a base commit.
lines 600 >"$repo/big.go"; lines 700 >"$repo/other.go"
printf '600 big.go\n' >"$repo/scripts/size-ratchet.allow"
git -C "$repo" add -A; git -C "$repo" -c user.name=t -c user.email=t@t commit -qm base
git -C "$repo" branch -f basebr
printf '600 big.go\n700 other.go\n' >"$repo/scripts/size-ratchet.allow"
run --base basebr >"$tmp/out" 2>&1 && bad "ADDED: new entry for existing file should fail" || { grep -q '^ADDED other.go' "$tmp/out" && ok || bad "ADDED msg: $(cat "$tmp/out")"; }
git -C "$repo" -c user.name=t -c user.email=t@t commit -qam wip; git -C "$repo" branch -f basebr HEAD
lines 650 >"$repo/big.go"; printf '650 big.go\n700 other.go\n' >"$repo/scripts/size-ratchet.allow"
run --base basebr >"$tmp/out" 2>&1 && bad "RAISED should fail" || { grep -q '^RAISED big.go' "$tmp/out" && ok || bad "RAISED msg: $(cat "$tmp/out")"; }
printf '# raise-approved: big.go needed for X\n650 big.go\n700 other.go\n' >"$repo/scripts/size-ratchet.allow"
run --base basebr >"$tmp/out" 2>&1 && ok || bad "override marker should pass: $(cat "$tmp/out")"
# A marker already present at the base is spent: a further raise fails.
git -C "$repo" -c user.name=t -c user.email=t@t commit -qam marker; git -C "$repo" branch -f basebr HEAD
lines 700 >"$repo/big.go"; printf '# raise-approved: big.go needed for X\n700 big.go\n700 other.go\n' >"$repo/scripts/size-ratchet.allow"
run --base basebr >"$tmp/out" 2>&1 && bad "spent marker should not allow another raise" || { grep -q '^RAISED big.go' "$tmp/out" && ok || bad "spent msg: $(cat "$tmp/out")"; }
lines 650 >"$repo/big.go"; printf '# raise-approved: big.go needed for X\n650 big.go\n700 other.go\n' >"$repo/scripts/size-ratchet.allow"
run --base basebr >"$tmp/out" 2>&1 && ok || bad "unchanged allowance passes: $(cat "$tmp/out")"

# --changed: only files changed since the base are counted.
git -C "$repo" -c user.name=t -c user.email=t@t commit -qam c; git -C "$repo" branch -f basebr HEAD
lines 800 >"$repo/untouched_big.go"; git -C "$repo" add untouched_big.go; git -C "$repo" -c user.name=t -c user.email=t@t commit -qm u; git -C "$repo" branch -f basebr HEAD
lines 900 >"$repo/new_big.go"
run --changed --base basebr >"$tmp/out" 2>&1 && bad "--changed should flag a new over-cap changed file" || { grep -q '^NEW   new_big.go' "$tmp/out" && ! grep -q untouched_big "$tmp/out" && ok || bad "--changed msg: $(cat "$tmp/out")"; }
rm "$repo/new_big.go"; git -C "$repo" reset -q --hard HEAD

run --changed --write >/dev/null 2>&1 && bad "--changed --write must be rejected" || ok

echo "size-ratchet tests: $pass passed, $fails failed"
[ "$fails" = 0 ]
